"""Review records for applied intermediate/world lessons; observations are teaching cases."""
REVIEWS = {
'C03': dict(finding='漂亮资产与可用资产混淆；替换验收要明确视觉层而非控制根。', decision='按用途、许可、兼容和修复成本选角色，决定哪些视觉变化可接受。', ai='列包内容和兼容风险，先接入一段已授权动画，只改视觉包装。', proof=['比较两份资产的比例、朝向、骨架和最小片段，说明选择或淘汰理由。','校准视觉脚底与前向，原控制/碰撞/镜头及拾取保持。'], diagnostic=('新角色脚悬空但胶囊仍正确落地，AI建议把重力加倍。视觉包装Y偏移与旧角色不同。你怎样先区分视觉错位和物理悬空？哪一层允许修改？','显示碰撞和视觉原点，核对胶囊落地；保持控制器，先恢复/调整视觉包装偏移。若胶囊也未落地再查物理，不凭外观改重力。','脚的位置和胶囊的位置是不是同一条证据？','分开检查视觉/物理，局部校准视觉后实走回归。'), target=2),
'C04': dict(finding='状态错误和过渡不舒服需要可区分数据，不应一律增加混合时间。', decision='决定动作切换条件与可接受脚滑，先修条件再调过渡。', ai='提供速度、落地状态、当前片段并排日志与可控过渡参数。', proof=['用条件表解释起停、空中松键及落地时选择的片段。','条件正确后小幅调过渡并连续测试，确认没有双重位移和视觉迟滞。'], diagnostic=('空中松开方向键后播放Idle；日志speed=0、grounded=false。AI建议把过渡从0.1秒改成1秒。先改条件还是混合时长？怎样同时检验正常站立和空中停水平运动？','先修Idle进入条件，水平速度零不等于落地。测试地面零速为Idle、空中零水平速度保持合适空中片段；条件正确后才调过渡。','长混合会改变grounded事实吗？','指出缺少地面条件并做两情境对照；不靠过渡遮错。'), target=1),
'C05': dict(finding='共享与独立不能只答定义，必须检查单件状态和公共资源的不同影响。', decision='指定哪些配置共享、哪些运行状态独立，只复制确有差异的资源。', ai='画实例/资源引用关系，准备单件修改及多件不受影响的对照。', proof=['对三个实例说明公共材质与个体消费状态的归属。','只改指定材质/状态并实测其余对象，避免复制无关大纹理。'], diagnostic=('三瓶药水引用同一个配置资源；拾取一瓶后三瓶都不可用，但位置各自独立。AI要复制三套全部贴图。怎样查看消费状态归属，既修个体状态又保留公共美术？','检查consumed等运行状态是否误存共享资源，按对象实例独立维护；材质/纹理仍可共享。先消耗一个再操作其余两件，验证状态与外观分开。','导致不可用的是纹理还是运行状态？','定位状态共享并最小分离，三对象正反验证保留公共资源。'), target=2),
'C06': dict(finding='门为选定机制时不应强制平台物理考试；重复触发仍需实证。', decision='先选门或平台之一，定义重复输入和恢复规则，平台只在所选路线验。', ai='把既有支点、状态和运动接成一个最小机制，提供绝对终点与回退。', proof=['对所选机制画出状态和固定目标位置/角度，重复请求不会无限叠加。','门：通过、阻挡与重开；平台路线另测站上、离开、恢复，不要求两条全做。'], diagnostic=('门正常一次到90度，连按三次到270度；AI提出把每次旋转改为30度。原约定是开门中忽略新请求。该修目标、状态还是按键次数？用什么顺序复测？','恢复固定90度目标及开门中拒绝/忽略新请求的约定；测试连按、已打开再按和重开，不用每次缩小增量补偿。','需求允许动作叠加吗？','明确状态许可和固定终态；重复输入及恢复测试满足已选门路线。'), target=1),
'C07': dict(finding='UV问题需要把几何尺寸和贴图映射分开，升级像素不是通用修复。', decision='先选择拼接尺寸/原点规则，再用格子判断拉伸还是纹理密度问题。', ai='准备三块可编辑墙及棋盘格，指出局部UV入口而非重做整套纹理。', proof=['按共同尺寸和连接点拼直段/转角，检查真实接缝。','固定几何修一个简单UV比例或密度，比较格子形状和世界尺寸。'], diagnostic=('三堵墙几何尺寸相同，A/B格子正方，C格子横向拉长；同一贴图。AI要把图从1K升4K。你先动图像还是C的UV？如何证明没有通过拉伸墙几何来伪装修好？','先核对并修C的UV映射，升分辨率不改拉伸比例。保留墙尺寸、接缝、相机和A/B基线，比较C格子变正且密度合理。','图像更多像素会改变它映射到墙的比例吗？','修映射并保持几何，格子形状与密度两项对照。'), target=2),
'C08': dict(finding='照明方案优劣要绑定动态需求与设备，不靠静态渲染图挑选。', decision='从实际动态角色和目标设备需求选择一种可行方案，不追最复杂GI。', ai='核对所用版本/渲染器支持，准备同条件最小静态与动态样本。', proof=['说明选择方案的表现、动态限制和实际成本证据。','角色跨亮暗区及移动对象实测，并分类Blender/Godot观感差异。'], diagnostic=('烘焙背景截图很美，后来移动装饰箱，旧位置仍有阴影。AI说换更高分辨率烘焙就会自动跟随。先确认哪项静态假设？怎样验收新动态需求？','先确认阴影来自预计算静态结果，移动对象后需相应更新/改动态方案；更高分辨率不是自动跟随。用移动对象前后和实际运行成本核对候选，不要求全部方案实现。','分辨率改变的是精细度，还是更新时机？','识别静态假设与新需求冲突；给可行更新/替代及动态验证，不以截图过关。'), target=1),
'C09': dict(finding='优化建议需要有否定条件和停止条件，不能因高级词汇而加系统。', decision='判断当前证据是否足够和是否已经达标，不把更低指标自动视为更好。', ai='整理首次/预热样本并提出一项低成本排除试验，不预报收益百分比。', proof=['把条件、症状、假设和结论分开写，提出可区分原因的实验。','据真实目标选择继续、撤回或停止，保留画面/功能检查。'], diagnostic=('关卡每次冷启动首次转弯卡顿，之后同路线正常。AI要全面降模型面数。你先比较哪些运行条件？什么结果会让你暂不支持持续绘制过重的假设？','比较冷启动首次与预热重复同路线并看加载/编译等相邻日志；只有首次尖峰提示先查初始化类原因，不能仅凭此断言唯一原因。若稳定段也持续慢再检持续成本。','异常持续存在，还是只在某个首次事件出现？','匹配运行阶段提出可否定假设，避免全面优化和确定性误归因。'), target=1),
'E01': dict(finding='导航是可选需求判断，不应让未选路线为了毕业实现寻路。', decision='先决定是否需要巡逻对象；选了才比较规划和实体可达性。', ai='准备简单路线与物理形状并排预览，不重写寻路算法。', proof=['结合本项目机关/巡逻选择明确要不要导航，未选可结束。','选导航时在门开闭及窄通道中实走，比较路径线和实体结果。'], diagnostic=('已选巡逻路线。路径线穿过门，但实体每次卡在门框；空旷区能正常走。AI建议删除门碰撞。先如何区分导航通道容积与实体宽度不匹配，怎样保留真实门？','查看门净宽、角色实体/导航尺寸及路径区域，先让导航与真实可通行空间一致。用同角色开阔区与门口对照，不删除阻挡来掩盖问题。','规划的一条线有没有包含角色实际体积？','限定已选路线，核对实体与可走区域并实测，不把路径图当完成。'), target=2),
'C10': dict(finding='提示与动作可能读不同的过期目标；要测切换目标而非单次按键。', decision='规定交互目标、距离、遮挡和状态条件，验收提示与实际作用对象一致。', ai='生成当前目标/提示/接受事件日志及有限交互链，不新增背包。', proof=['在范围内外和遮挡条件下核对提示及允许结果。','在两个目标间切换后只操作当前对象，状态和显示各自归属清楚。'], diagnostic=('先靠近门A出现提示，离开再靠近按钮B，提示已写B，但按键仍开A。AI只改提示颜色。你先查哪个引用/条件，怎样避免把显示正确当目标正确？','核对动作使用的当前目标是否仍是A，目标变化时清理过期引用并重新检查有效/范围条件。按A→离开→B连续测试日志与对象状态，不只看Label。','提示和执行读的是同一个有效目标吗？','查执行目标和清理时机；两对象连续切换验证。'), target=2),
'C11': dict(finding='文件写入成功不等于恢复可靠；故障练习必须保护唯一原档。', decision='决定保存最小内容、失败策略及可覆盖范围；不让AI自动清空唯一数据。', ai='只在沙盒副本生成正常/旧版/损坏数据测试并解释读写策略。', proof=['区分持久进度、偏好和临时表现，给出恢复需求。','在副本测试缺失/旧/损坏数据，保留原件且能重开恢复设置。'], diagnostic=('旧档少一个新字段。AI把任何异常都当首次运行，并立即用默认值覆盖原档；游戏能启动。你能接受什么、必须阻止什么？给一个不接触唯一原件的测试。','可提供安全默认启动，但不能把未知失败等同无数据并立即覆盖。复制旧档到沙盒，按版本/缺字段策略加载，核对原内容未变与恢复结果；损坏单独处理。','启动成功和旧进度保住是同一证据吗？','区别失败类型与恢复目标，副本测试且原件不覆盖。'), target=2),
'C12': dict(finding='打包与源资产再分发是不同发布对象；需要真实包和来源证据。', decision='选一个目标平台，确认首次启动与资源分发范围，不把许可证猜测当结论。', ai='准备导出依赖清单和干净数据测试步骤，标出许可信息缺口。', proof=['实际目标包在干净数据条件走完启动、控制、收齐、重开/退出路径。','逐项核对来源和所选发布物范围，明确未授权源资产不能直接公开。'], diagnostic=('作者电脑导出包正常，另一台缺贴图。AI给出作者私人磁盘的绝对路径，声称修复。怎样检查依赖和打包范围？课程仓库与游戏包中的素材应分别核对什么？','检查项目内相对资源路径、大小写与导出包含，真实包重测；不依赖作者私人目录。另核对游戏使用与公开源资产分发的实际许可范围，缺文本就标待确认。','这个依赖是否存在于交付包里，而不是只在作者电脑？','真实包依赖修复与干净重测；区分分发对象，不作通用法律保证。'), target=1),
'D07': dict(finding='结业材料齐全不能自动证明精致Demo可玩，且增强版必须条件化验收。', decision='明确基础版或增强版，按当前版本证据决定交付还是缩减未选扩展。', ai='组织最终路线/回归表及缺口清单，不替学员捏造通过记录。', proof=['从首次启动连续走完三段回路、十星、完成、重开，解释地图和美术取舍。','同一构建对齐功能/性能/来源证据；选增强版才验证训练角，可禁用后主线仍通。'], diagnostic=('材料有漂亮入口图、作者编辑器录像和旧构建的性能记录；准备交付的新包加入训练角，却没测重开。AI称材料都齐了。哪些证据不能直接转用？基础版与增强版如何处理？','截图不证明完整路线，旧构建数据需确认变更相关性，新包必须测试实际完成/重开；增强版加训练角专项及禁用回归。可选扩展未达标可回退基线交基础版，但不能删基础重开需求。','证据对应的是同一交付对象、版本和范围吗？','匹配版本/过程证据；基础底线不删，增强门槛条件化。'), target=2),
'C01': dict(finding='大地图容易变成面积作业；应测地标视线、实际到达与回程。', decision='选择一处路线修正，保持控制器基线，用玩家观察点评估收益。', ai='连接庭院、林路、观景台的最小灰盒和十星清单，不安装大地形系统。', proof=['用地标与回路解释路线和回程，避免只有扩大地面。','实走十星与返回路；记录一处修改前后迷路/落点/通过性的变化。'], diagnostic=('俯视图能从林路到观景台；玩家视角桥入口被大石遮住，镜头也看不到桥面。AI要把跑速翻倍减少空跑。先用哪一个位置的观察，怎样做不改控制器的最小对照？','回到林路路口的固定玩家机位，先只移开/隐藏该石观察桥入口，再实走桥面与返回路；视线与物理可达分别验。保持速度、跳跃、相机基线，不用跑速补路径问题。','问题出在旅行时间，还是玩家看不到下一步？','指定机位和单项布局对照；实际到达/回程，保留控制器。'), target=2),
'C02': dict(finding='世界美化不能以单张图替代路线和成本验收，先样板再扩展。', decision='决定共同风格和留白，保留路线净空，只推广已验证样板。', ai='按允许清单替换一组环境资产，记录引用与范围，不自动铺满全图。', proof=['同一转角按大形→光色→细节制作有理由的样板并说明留空位置。','固定三机位A/B后实走整圈，检查装饰遮挡、碰撞与已约定成本。'], diagnostic=('美化后观景台跳跃经常失败；关卡几何和控制参数未改，新树叶挡住落点。AI要提高jump_velocity。你先如何检验视线问题？若树枝还有意外碰撞又如何区分？','先只关闭可见树叶比较落点可读性并保持物理；再在副本独立检查/切换新增碰撞，分别验证视觉与阻挡。不要先改已通过的跳跃，确认后局部移植被并实走回归。','分别控制看见什么与撞到什么，别一次全关。','视觉/碰撞分开对照，局部调整及整圈回归；不以手感参数掩盖美术问题。'), target=2),
}
